-- Gold Query
SELECT County, COUNT(Virtual) FROM schools WHERE (County = 'San Diego' OR County = 'Santa Barbara') AND Virtual = 'F' GROUP BY County ORDER BY COUNT(Virtual) DESC, County NULLS LAST LIMIT 1;

/*
Gold Result:
('San Diego', 8)
*/

